use dao_shell::{core::Cancellation,diagnostics::coverage};
fn main(){let c=Cancellation::default();let p=std::process::id();let io=coverage::io(p,sysinfo::System::new_all().process(sysinfo::Pid::from_u32(p)).unwrap().start_time());let mut gpu=coverage::Gpu::new(true);std::thread::sleep(std::time::Duration::from_millis(1100));let g=gpu.sample();println!("{}",serde_json::to_string_pretty(&serde_json::json!({"power":coverage::power(),"own_process_io_available":io.is_some(),"gpu_counters":g,"store":coverage::store_apps(&c),"network":coverage::network_config(&c).unwrap_or_else(|_|serde_json::json!({"error":"unavailable"})),"startup":coverage::startup(serde_json::json!({"source":"user","limit":4}),&c).unwrap()})).unwrap());}
